ee:message.ee:set-payload:
%dw 2.0
output application/json
fun getDirecciones(idDireccion) = do {
    var direcciones = data.datosBasicos.direcciones
---
((direcciones default []) filter ((dir, index) -> dir.idDireccion == idDireccion) default [])[0]
}
var convertPayload = (flatten(valuesOf(payload) map ((item, index) -> item.*payload)) default []) as Array
var data = convertPayload map ((item, index) ->
{
    (item.field as String): item.data
}
) reduce ((item, acc) -> item ++ acc)
var datosBasicos = data.datosBasicos
var servicios = {
    servicios: data.servicios.servicios default []
    map ((ser, index) ->
    ser ++ {
        direccionInstalacion: getDirecciones(ser.idDireccionInstalacion)
    }),
    serviciosActivos: data.servicios.serviciosActivos  default []
    map ((ser, index) ->
    ser ++ {
        direccionInstalacion: getDirecciones(ser.idDireccionInstalacion)
    }),
}
---
(data.datosBasicos default {}) ++ {
    (servicios: servicios) if(vars.fields contains "servicios"),
    (notificaciones: data.notificaciones) if(vars.fields contains "notificaciones"),
    (interacciones: data.interacciones) if(vars.fields contains "interacciones"),
    (pqr: data.pqr) if(vars.fields contains "pqr"),
    (facturacion: data.facturacion) if(vars.fields contains "facturacion"),
    (retenciones: data.retenciones) if(vars.fields contains "retenciones"),
    (promociones: data.promociones) if(vars.fields contains "promociones"),
    (ordenes: data.ordenes) if(vars.fields contains "ordenes"),
    (fallasMasivas: data.servicios.fallasMasivas) if(vars.fields contains "fallasMasivas"),
}

