ee:variables.ee:set-variable:
%dw 2.6
import modules::common
output application/java
var servicios = (
(common::camelizeData(common::underscoreData(vars.mdmCdServicioResponse as Array default []))
  map ((item, index) -> {
    collection: "Servicio",
    serviceAccount: item.idCuentaServicio,
    tecnology: item.bundle.tipoServicio,
    fallasFilter: true
  }))
++ (common::camelizeData(common::underscoreData(vars.mdmServicioActivoResponse as Array default []))
map ((item, index) -> {
    collection: "Servicio Activo",
    serviceAccount: item.codigoServicio,
    tecnology: item.producto,
    fallasFilter: true
  }))
) as Array default []
---
(servicios filter ($.fallasFilter))
  map ((item, index) -> {
    serviceAccount: item.serviceAccount,
    tecnology: item.tecnology,
  })

