%dw 2.0
import modules::common
output application/java
var ordenesAgendas = common::camelizeData(common::underscoreData(vars.ordenesAgendas default []))
fun getAgendamientos(ordenes) = do {
    var data = common::camelizeData(common::underscoreData(ordenes)) as Array default []
---
data map ((item, index) ->
    item ++ {
        agendas: (ordenesAgendas filter ($.apptNumber == item.numeroOrden) default [])
    }
)
}
---
{
	field: "ordenes",
	data: {
		fijas: {
			mdmOrden: getAgendamientos(vars.mdmOrdenResponse as Array default []),
			mdmOrdenCompletadas: getAgendamientos(vars.mdmOrdenCompletadasResponse as Array default [])
		},
		moviles: {
			mdmCdOrden: getAgendamientos(vars.mdmCdOrdenResponse as Array default []),
			mdmCdOrdenCompletadas: getAgendamientos(vars.mdmCdOrdenCompletadasResponse as Array default [])
		}
	}
}

